[DataContractAttribute]
public class TFMMenuConfigContract
{
    str            pageId;
    str            title;
    str            iconName;
    boolean        standard;
    boolean        mandatory;
    boolean        offline;
    boolean        pageOffline;
    boolean        hide;
    boolean        promoted;
    int            updated;


}

Method.Source:
[DataMemberAttribute]
public str parmPageId(str _pageId = pageId)
{
    pageId = _pageId;
    return pageId;
}

