{
    iconName = _iconName;
    return iconName;
}

[DataMemberAttribute]
public boolean parmIsStandard(boolean _standard = standard)
{
    standard = _standard;
    return standard;
}

[DataMemberAttribute]
public boolean parmIsMandatory(boolean _mandatory = mandatory)
{
    mandatory = _mandatory;
    return mandatory;
}

[DataMemberAttribute]
public boolean parmIsHide(boolean _hide = hide)
{
    hide = _hide;
    return hide;
}

[DataMemberAttribute]
public boolean parmIsOffline(boolean _offline = offline)
{
    offline = _offline;
